<?php

/**
 * Install BJCP 2026 mead styles. Mirrors styles_bjcp_2025_update.php's
 * shape exactly (this update's own category only - mead - not a duplicated
 * beer/cider catalog; beer/cider continue to resolve from the existing
 * BJCP2021/BJCP2025-tagged rows via the version-resolution branches
 * elsewhere in the app).
 */

$data = array(
  array('brewStyleGroup' => 'M1','brewStyleNum' => 'A','brewStyle' => 'Dry Mead','brewStyleCategory' => 'Traditional Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A mead without significant residual sweetness, allowing more of the natural honey aromatics to be appreciated without the associated sweetness of raw honey. Lower levels of sweetness may allow more of the fermentation, conditioning, and aging bouquet to be perceived. Has a similar balance, body, finish, and flavor intensity as found in the full range of dry white wines.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M1/M1A/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '0','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => 'Brothers Drake Wild Ohio, Honeygirl Meadery Orange Blossom, Heidrun Meadery (all dry sparkling single-varietals), Intermiel Bouquet Printanier, White Winter Dry Mead','brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels; sweetness is restricted to dry in this style. Honey varieties may be declared.<br><br>May seem more wine-like than other mead types since the sweetness associated with honey is largely absent. Dry mead can place more emphasis on the residual fermentation characteristics of the honey and yeast, as these are the primary means of adding complexity.'),
  array('brewStyleGroup' => 'M1','brewStyleNum' => 'B','brewStyle' => 'Semi-Sweet Mead','brewStyleCategory' => 'Traditional Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A mead with a noticeable, balanced honey sweetness. Increased honey character and body is noticeable, as compared to a M1A Dry Mead. Acid and tannin levels support the sweetness, but finishing sweetness does not dominate the mead. Has a similar balance, body, finish, and flavor intensity as found in the full range of semi-sweet to sweet white wines.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M1/M1B/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '0','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Colony Meadery Straight, No Chaser; Intermiel Verge d'Or; Rabbit's Foot Tupelonium; Redstone Traditional Mountain Honey Wine; Sky River Dry Mead",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels; sweetness is restricted to semi-sweet in this style. Honey varieties may be declared.<br><br>Semi-Sweet Mead is characterized by its balanced sweetness. The actual range of sweetness can be quite broad, since it needs to cover the space between dry and sweet meads.'),
  array('brewStyleGroup' => 'M1','brewStyleNum' => 'C','brewStyle' => 'Sweet Mead','brewStyleCategory' => 'Traditional Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A mead with significant honey sweetness. Increased honey character and body is noticeable, as compared to a M1B Semi-Sweet Mead. Acid and tannin levels support the sweetness, but the finishing sweetness is a major flavor component. Has a similar balance, body, finish, and flavor intensity as found in the full range of well-made dessert wines (such as Ice Wine).','brewStyleLink' => 'https://www.bjcp.org/style/2026/M1/M1C/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '0','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Intermiel Benoîte, Moonlight Sensual, Prairie Rose Traditional Sweet, Rabbit's Foot Sweet Mead, Schramm's Mead Sunflowers, White Winter Sweet Mead, Winehaven Stinger",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels; sweetness is restricted to sweet in this style. Honey varieties may be declared.<br><br>Sweet Mead is characterized by noticeable sweetness. Some examples may seem similar to well-made dessert wines that have sufficient acidity and tannin to balance the prominent sweetness. The most common flaw is a raw honey sweetness that makes the finished product taste under-fermented.'),
  array('brewStyleGroup' => 'M2','brewStyleNum' => 'A','brewStyle' => 'Cyser','brewStyleCategory' => 'Melomel','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Cyser is a melomel made with apples (generally unfermented cider, but can be a must from table or cider apples) or other pome fruit (pears, quince). Like a M1 Traditional Mead with a noticeable pome fruit character. A wide range of outcomes are possible depending on choices of the base mead and additional ingredients, but the final product should be balanced, pleasant, and enjoyable. The fruit character should be harmonious with the base mead, and not seem solely like a cider.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M2/M2A/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Brothers Drake Pollinator, Redstone Apple Nectar, Schramm's Mead Apple Reserve, White Winter Cyser, Williamson Idunn",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Honey varieties may be declared. Fruit must be declared. If fruit varieties are specified, a varietal character will be expected.<br><br>Examples with a relatively low honey character may be evaluated better as a C3C Experimental Cider. A spiced cyser should be entered as a M3C Fruit and Spice Mead. A cyser with additional non-pome fruit should be entered as an M2E Other Fruit Mead. A cyser with additional ingredients should be entered as an M4F Experimental Mead.'),
  array('brewStyleGroup' => 'M2','brewStyleNum' => 'B','brewStyle' => 'Pyment','brewStyleCategory' => 'Melomel','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Pyment is a melomel made with wine or table grapes (generally from juice or must). Pyments can be red, white, or rosé, just as with wine. Like a M1 Traditional Mead with a noticeable wine-like character. A wide range of outcomes are possible depending on choices of the base mead and additional ingredients, but the final product should be balanced, pleasant, and enjoyable. The fruit character should not completely dominate the mead.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M2/M2B/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => 'Aurum Verdelho Pyment, Hammen Family Orchard Pyment, Meadow Vista Ostara, Mount Stirling Red Pyment Mead, Remeadies Sour Grapes','brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Honey varieties may be declared. Fruit must be declared. If grape varieties are specified, a varietal character will be expected.<br><br>A Pyment that also contains other fruit should be entered as an M2E Other Fruit Mead. Spiced pyments (hippocras) should be entered as a M3C Fruit and Spice Mead. Fruited meads with other non-fruit ingredients should likely be entered as M4F Experimental Mead.'),
  array('brewStyleGroup' => 'M2','brewStyleNum' => 'C','brewStyle' => 'Berry Mead','brewStyleCategory' => 'Melomel','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => "A Berry Mead is an entry category for melomels made with one or more type of berry, such as raspberries, blueberries, blackberries, currants (black, red, and white), strawberries, boysenberries, elderberries, marionberries, mulberries, lingonberries, huckleberries, cranberries, etc. Generally, any fruit with 'berry' in the name would qualify. Berries can have seeds, but do not have stones/pits. Like a M1 Traditional Mead with a noticeable fruit character. A wide range of outcomes are possible depending on choices of the base mead and additional ingredients, but the final product should be balanced, pleasant, and enjoyable. The fruit character should not completely dominate the mead.",'brewStyleLink' => 'https://www.bjcp.org/style/2026/M2/M2C/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Moonlight Wild, Prairie Rose Honeyberry, Rabbit's Foot Raspberry Mead, Redstone Boysenberry Nectar, Schramm's Mead Black Heart, St. Ambrose Rhythm and Blues, White Winter Strawberry Mead",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Honey varieties may be declared. Fruit must be declared.<br><br>A Berry Mead that also contains other fruit should be entered as an M2E Other Fruit Mead. Spiced versions should be entered as a M3C Fruit and Spice Mead. Fruited meads with other non-fruit ingredients should likely be entered as M4F Experimental Mead.'),
  array('brewStyleGroup' => 'M2','brewStyleNum' => 'D','brewStyle' => 'Stone Fruit Mead','brewStyleCategory' => 'Melomel','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Stone Fruit Mead is an entry category for melomels made with one or more stone fruit, such as cherries, plums, peaches, apricots, and mangoes. Stone fruit are fleshy fruit with a single large pit or stone. Like a M1 Traditional Mead with a noticeable fruit character. A wide range of outcomes are possible depending on choices of the base mead and additional ingredients, but the final product should be balanced, pleasant, and enjoyable. The fruit character should not completely dominate the mead.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M2/M2D/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Moonlight Entice, Prairie Rose Chokecherry, Redstone Peach Reserve, Redstone Sunshine Nectar, Schramm's Mead The Statement, White Winter Honey of a Plum",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Honey varieties may be declared. Fruit must be declared.<br><br>A Stone Fruit Mead that also contains other fruit should be entered as an M2E Other Fruit Mead. Spiced versions should be entered as a M3C Fruit and Spice Mead. Fruited meads with other non-fruit ingredients should likely be entered as M4F Experimental Mead.'),
  array('brewStyleGroup' => 'M2','brewStyleNum' => 'E','brewStyle' => 'Other Fruit Mead','brewStyleCategory' => 'Melomel','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'The Other Fruit Mead style is for melomels made with any fruit not associated with any previous melomel style, or with a combination of fruit from multiple fruit mead styles (such as grapes and stone fruit). Some examples include citrus fruit, dried fruit (dates, prunes, raisins, etc.), fig, pomegranate, prickly pear, banana, pineapple, guava, and most other tropical fruit. If in doubt, enter the fruit here - judges should be flexible in allowing fruit not explicitly named in other styles. Like a M1 Traditional Mead with a noticeable fruit character. A wide range of outcomes is possible depending on choices of the base mead and additional ingredients, but the final product should be balanced, pleasant, and enjoyable. The fruit character should not completely dominate the mead.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M2/M2E/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Intermiel Black Currant and Citrus Sparkling Mead, Lost Cause Malum, Moonlight Desire, Redstone Blood Orange Nectar, Redstone Passion Fruit Nectar, Schramm's Mead Apple Crandall Reserve",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Honey varieties may be declared. Fruit must be declared.<br><br>This is a catch-all style for the Melomel category, so only meads that do not fit in a prior fruited mead style should be entered here. Spiced versions should be entered as a M3C Fruit and Spice Mead. Fruited meads with other non-fruit ingredients should likely be entered as M4F Experimental Mead.'),
  array('brewStyleGroup' => 'M3','brewStyleNum' => 'A','brewStyle' => 'Metheglin','brewStyleCategory' => 'Spiced Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => "A Metheglin contains one or more culinary spices or herbs, but does not include any vegetables. This explicitly includes coffee, chocolate, nuts (or anything with 'nut' in the name, including coconut, rose petals and hips, spruce tips, hibiscus, fruit peels and zest, and the like. Like a M1 Traditional Mead with a noticeable herb or spice character. A wide range of outcomes are possible depending on choices of the base mead and additional ingredients, but the final product should be balanced, pleasant, and enjoyable. The herb or spice character should not completely dominate the mead.",'brewStyleLink' => 'https://www.bjcp.org/style/2026/M3/M3A/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Colony Meadery Moravian Spice Cake, Prairie Rose Vanilla Cinnamon, Redstone Juniper Berry Mountain Honey Wine, Schramm's Mead Nutmeg, Sky River Chamomile Mead, White Winter Holiday Harbor",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Honey varieties may be declared. Perceivable herbs, spices, or spice blends must be declared.<br><br>If spices are used in conjunction with other ingredients such as fruit, cider, or other fruit-based fermentables, then the mead should be entered as a M3C Fruit and Spice Mead. If spices are used in combination with other ingredients, then the mead should be entered as an M4F Experimental Mead. Often, a blend of spices may give a character greater than the sum of its parts. The better examples of this style use spices deftly; when more than one spice is used, they are carefully selected so that they blend harmoniously.'),
  array('brewStyleGroup' => 'M3','brewStyleNum' => 'B','brewStyle' => 'Vegetable Mead','brewStyleCategory' => 'Spiced Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Vegetable Mead must contain at least one vegetable and may contain one or more herbs or spices. The following ingredients are explicitly included as vegetables: rhubarb, pumpkins, and chile peppers. Culinary transformations of ingredients (e.g., roasted peppers) are also allowable. Like a M1 Traditional Mead with a noticeable vegetable and optional herb or spice character. A wide range of outcomes are possible depending on choices of the base mead and additional ingredients, but the final product should be balanced, pleasant, and enjoyable. The spice, herb, or vegetable (SHV) character should not completely dominate the mead.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M3/M3B/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => 'iQhilika Africa Birds Eye Chili Mead, Lyme Bay Winery Chilli Mead, Sky River Red Pepper Mead','brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Honey varieties may be declared. Entrants must specify added vegetable(s). Perceivable herbs, spices, or spice blends must be declared. Meads with spicy-hot flavors should specify the level of heat (mild, medium, hot) to assist judges with ordering the samples.<br><br>If spices are used in conjunction with other ingredients such as fruit, cider, or other fruit-based fermentables, then the mead should be entered as a M3C Fruit and Spice Mead. If spices are used in combination with other ingredients, then the mead should be entered as an M4F Experimental Mead.'),
  array('brewStyleGroup' => 'M3','brewStyleNum' => 'C','brewStyle' => 'Fruit and Spice Mead','brewStyleCategory' => 'Spiced Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Fruit and Spice Mead is a mead containing one or more fruits and one or more spices, herbs, or vegetables. Basically, this is any mead containing at least one allowable specialty ingredient from each of categories M2 and M3. Like a M1 Traditional Mead with a noticeable fruit and spice, herb, or vegetable (SHV) character. A wide range of outcomes are possible depending on choices of the base mead and additional ingredients, but the final product should be balanced, pleasant, and enjoyable. The SHV character should not completely dominate the mead.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M3/M3C/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Intermiel Pear & Ginger Sparkling Mead, Lost Cause Banshee Part II, Moonlight Kurt's Apple Pie, Prairie Rose Strawberry Rhubarb, Rabbit's Foot Chocolate Raspberry Love, Schramm's Mead Apple Crisp, St. Ambrose Shotgun Wedding",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Honey varieties may be declared. Entrants must specify added fruits and SHVs. Meads with spicy-hot flavors should specify the level of heat (mild, medium, hot) to assist judges with ordering the samples.<br><br>If only combinations of herbs or spices are used, enter as a M3A Metheglin. If only combinations of fruits are used, enter as an M2E Other Fruit Mead. If other types of ingredients are used, enter as an M4F Experimental Mead. Often, a blend of fruits and SHVs may give a character greater than the sum of its parts. Sensory components derived from fruit and SHV additions should be harmonious and supportive of those from the base mead, and should not clash.'),
  array('brewStyleGroup' => 'M4','brewStyleNum' => 'A','brewStyle' => 'Braggot','brewStyleCategory' => 'Specialty Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Braggot is a mead made with malt or beer. A braggot should be discernable as a mead and not simply a honey beer, but specific ratios of honey to beer are not mandated. Like a M1 Traditional Mead with a supporting malt or beer character. A wide range of outcomes are possible depending on choices of the base mead and additional ingredients. The mead character should be stronger than in honey beers, but the blend of mead and beer should be pleasant and well-integrated.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M4/M4A/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '0','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Atlantic Brewing Brother Adam's Bragget Honey Ale, Kuhnhenn Braggot Mead, Meadow Vista Pictish Beast, Staropolskie Miodne, Tributary Biére de Miel",'brewStyleEntry' => "Entrants must specify sweetness, carbonation, and strength levels. Entrants may identify details such as honey varieties, base beer styles, or types of malt used to allow judges to discern the meadmaker's intent. A classic base beer style is not required, but entrants should provide enough information to assist judges with ordering the samples. Specifying whether or not hops were used is often helpful to judges.<br><br>Sometimes known as bracket or brackett. Products with a relatively low proportion of honey should be entered as a beer in the 31B Alternative Sugar Beer style. Common flaws in beer (such as oxidation) are also flaws in braggots."),
  array('brewStyleGroup' => 'M4','brewStyleNum' => 'B','brewStyle' => 'Bochet','brewStyleCategory' => 'Specialty Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Bochet is a modern interpretation of a historical concept involving heated or caramelized honey, and may optionally include spices and fruits. Like a Traditional Mead with a noticeable caramelized honey character, but not burnt, harsh, or acrid notes. Acidity levels should be balanced. Optional spice and fruit additions should enhance, not dominate, the base bochet character.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M4/M4B/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '0','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Lost Cause's Wicked Counsel, Manic Meadery's Elliot Bochet, Prairie Rose Caramel Apple, Sky River Brochet Mead, Zymarium Meadery's Swam Intelligence",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. If spices or fruits are used, they must be specified. Honey varieties and base style are optional.<br><br>While versions inspired by historical references may feature burnt honey flavors, this character is undesirable in modern bochet. A major fault is excessive caramelization that creates acidity, astringency, and umami flavors that thin the body, increase the bitterness, and wash out the flavors.'),
  array('brewStyleGroup' => 'M4','brewStyleNum' => 'C','brewStyle' => 'Polish Mead','brewStyleCategory' => 'Specialty Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Polish Mead is family of styles with a common background and character that is legally defined within the European Union (EU) with a Traditional Specialty Guaranteed mark under the Staropolski Tradycyjny (Traditional Historical Polish) name. The BJCP style definition aligns with these EU specifications. Polish mead is categorized by the ratio of the volume of honey and water used, with identified versions as Czwórniak (1:3, roughly equivalent to Semi-Sweet Mead), Trójniak (1:2, roughly equivalent to Sweet Mead), Dwójniak (1:1), and Półtorak (1:0.5). However, without a distinctive character, Polish mead would be simply any other mead made with restrictive recipe ratios. This style therefore describes a subset of the family of Polish meads that has a distinctive traditional character of maturity and mouthfeel. Stronger or denser versions of Polish Mead are characterized by a viscous mouthfeel, aged character, and often sweet finish while the weaker or thinner versions may seem superficially similar to meads in the M1 Traditional Mead category, and derivative fruit and spiced versions. This style is intended for meads that exhibit this distinctive Polish character. <table class="table table-condensed table-bordered" style="max-width:400px;"><caption>Vital Statistics (meads without fruit additions; those using fruit would be higher)</caption><thead><tr><th>Variety</th><th>ABV</th><th>Min Age</th><th>OG</th><th>FG</th></tr></thead><tbody><tr><td>Czwórniak</td><td>9-12%</td><td>9 mo.</td><td>1.090</td><td>1.012-1.033</td></tr><tr><td>Trójniak</td><td>12-15%</td><td>1 yr.</td><td>1.144</td><td>1.024-1.045</td></tr><tr><td>Dwójniak</td><td>15-18%</td><td>2 yrs.</td><td>1.215</td><td>1.065-1.089</td></tr><tr><td>Półtorak</td><td>15-18%</td><td>3 yrs.</td><td>1.286</td><td>1.150-1.170</td></tr></tbody></table>','brewStyleLink' => 'https://www.bjcp.org/style/2026/M4/M4C/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => 'Ami Honey Trójniak Sandomierski, Apis Czwórniak Korzenny, Apis Półtorak Jadwiga, Augustowska Trójniak Jabłko na Miodzie, Dziki Miód Trójniak Porzeczkowiec, Jaros Dwójniak Maliniak, Jaros Trójniak Trybunalski, Mazurskie Półtorak Piasecki','brewStyleEntry' => 'Entrants must specify the Polish style variety (Czwórniak, Trójniak, Dwójniak, or Półtorak). Strength and carbonation are assumed to be within specification. Sweetness level must be declared. Any special ingredients (fruits, spices, hops) must be declared. Honey varieties may be declared.<br><br>A traditional product made for over a millennium in a region spanning current Poland and Lithuania, and parts of Belarus and Ukraine. Ingredients from this area are considered traditional. All varieties of Polish Mead can contain fruits, spices, and hops. When using fruit, fruit juice is traditional and replaces at least 30% of the volume of water in the mandated ratios. Dwójniak and Półtorak are traditionally produced as Trójniak, then fed the remaining honey late in fermentation or during aging. Modern versions may be fortified with distilled spirits. Modern versions using non-traditional ingredients or versions using other ratios of honey to water should be entered as M4F Experimental Mead, if they still retain the Polish character.'),
  array('brewStyleGroup' => 'M4','brewStyleNum' => 'D','brewStyle' => 'Wood-Aged Mead','brewStyleCategory' => 'Specialty Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Wood-Aged Mead is a mead with a noticeable amount of wood character, greater than a background level. Meads aged on a wood other than oak can be entered here, if there is a noticeable varietal wood character to the mead. Any prior mead style in the guidelines may be used as a base style. Any style of mead that uses wood at a noticeable level, but still in a way that is balanced, pleasant, and enjoyable. The wood character should not completely dominate the mead, but can play up to an equal role as the other ingredients.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M4/M4D/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Brothers Drake Honey Oak, Intermiel Chouchen'n Signé Macle, Intermiel Médiéval, Lost Cause Wolf, Rabbit's Foot Mead of Poetry, Silver Hand Virginia Tonight",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Entrants must specify a base mead style, as well as any components typically required by that base style. Entrants must specify the type of wood used, and may specify the toast or char level.<br><br>Meads featuring only a background character of wood should be entered as their base style. Those meads featuring a mix of M4D Wood-Aged Mead and M4E Barrel-Aged Mead should be entered as M4E Barrel-Aged Mead.'),
  array('brewStyleGroup' => 'M4','brewStyleNum' => 'E','brewStyle' => 'Barrel-Aged Mead','brewStyleCategory' => 'Specialty Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'A Barrel-Aged Mead is similar to the Wood-Aged Mead category, except that meads are aged in barrels that previously held other contents (beer, wine, cider, spirits, other food products) and now feature both the wood and the previous contents as added character. Any style of mead that features a used barrel character at a noticeable level, but still in a way that is balanced, pleasant, and enjoyable. The barrel character should not completely dominate the mead, but can play up to an equal role as the other ingredients. Both the barrel and the prior contents of the barrel should play a role in the final product.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M4/M4E/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Lost Cause The Connoisseur, Moonlight Utopian X, Prairie Rose Cherry Wood, Rabbit's Foot Barrel Aged Odin, Redstone Barrel Aged Black Raspberry Mountain Honey Wine, Schramm's Mead The Icon Reserve, Sky River Solas Honey Wine",'brewStyleEntry' => 'Entrants must specify sweetness, carbonation, and strength levels. Entrants must specify a base style, as well as any components typically required by the base style. Entrants must specify the type of barrel used, prior barrel contents, and may specify additional process details.<br><br>Meads featuring only a base character of wood (even if barrel-derived) should be entered in M4D Wood-Aged Mead. Those meads featuring a mix of M4D Wood-Aged Mead and M4E Barrel-Aged Mead should be entered in this style.'),
  array('brewStyleGroup' => 'M4','brewStyleNum' => 'F','brewStyle' => 'Experimental Mead','brewStyleCategory' => 'Specialty Mead','brewStyleVersion' => 'BJCP2026','brewStyleOG' => '','brewStyleOGMax' => '','brewStyleFG' => '','brewStyleFGMax' => '','brewStyleABV' => '','brewStyleABVMax' => '','brewStyleIBU' => 'N/A','brewStyleIBUMax' => 'N/A','brewStyleSRM' => 'N/A','brewStyleSRMMax' => 'N/A','brewStyleType' => '3','brewStyleInfo' => 'An Experimental Mead is a mead that does not fit into any other mead category or style. No mead can be "out of style" for this category unless it fits into another existing mead style. Depends on the declared experimental nature, but should be recognizable as mead, contain identifiable experimental components, and be pleasant to drink.','brewStyleLink' => 'https://www.bjcp.org/style/2026/M4/M4F/','brewStyleActive' => 'Y','brewStyleOwn' => 'bcoe','brewStyleReqSpec' => '1','brewStyleStrength' => '1','brewStyleCarb' => '1','brewStyleSweet' => '1','brewStyleTags' => '2026','brewStyleComEx' => "Lost Cause Goblin King, Lost Cause Lemon's Cello, Prairie Rose Mojito, Redstone Nectar of the Hops, Samuel Adams Honey Queen, St. Ambrose Razzputin, White Winter Black Harbor",'brewStyleEntry' => "Entrants must specify sweetness, carbonation, and strength levels. The entrant must specify the experimental nature of the mead in sufficient detail to justify its entry as this style.<br><br>Some examples of this category include: <ul><li>Mead that blends multiple mead styles (unless the combination fits elsewhere, such as M3C Fruit and Spice Mead)</li><li>Mead using additional fermentable or unfermentable sweeteners (e.g., maple syrup, molasses, brown sugar, agave nectar, lactose)</li><li>Mead using additional ingredients (e.g., liqueurs, distilled spirits, smoke, dairy-derived products, hops)</li><li>Mead using alternative processes, methods, or techniques (e.g., icing, smoking, souring)</li><li>Mead fermented with non-traditional yeasts or bacteria that produce a noticeable effect (e.g., Brettanomyces, Lactobacillus, Belgian lambic, sake)</li><li>Regional, traditional, historical, or indigenous mead not in the guidelines</li><li>'Concept' mead meant to evoke a cocktail, dessert, or other food or drink (unless it fits an established style)</li><li>Mead that otherwise meets existing guideline descriptions except that it is noticeably outside listed style parameters or uses non-traditional ingredients</li></ul> This list is representative, and should not be interpreted as restricting experimental meads to only these examples. The experimental nature should not include anything illegal in the jurisdiction where it is produced or judged, or anything potentially dangerous to judges.")
);

// Insert per-row (not insertMulti()) and skip any style that already exists.
// check_new_style() alone is NOT safe here - it matches only on
// brewStyleGroup/brewStyleNum/brewStyle, not brewStyleVersion, and 8 of
// these 17 mead names (M1A/B/C, M2A-D, M4A) are unchanged from the existing
// BJCP2021-tagged rows of the same group/num/name. Using check_new_style()
// directly would find those older rows and wrongly skip inserting the new
// BJCP2026 ones. This inline check adds brewStyleVersion to the match so
// only a genuine BJCP2026 duplicate is skipped.
$update_table = $prefix."styles";
$inserted = 0;
$skipped = 0;
$insert_errors = FALSE;
foreach ($data as $row) {
  $db_conn->where('brewStyleGroup', $row['brewStyleGroup']);
  $db_conn->where('brewStyleNum', $row['brewStyleNum']);
  $db_conn->where('brewStyle', $row['brewStyle']);
  $db_conn->where('brewStyleVersion', 'BJCP2026');
  $row_check = $db_conn->getOne($update_table, "COUNT(*) as 'count'");
  if ($row_check['count'] > 0) {
    $skipped++;
    continue;
  }
  if ($db_conn->insert($update_table, $row)) $inserted++;
  else {
    $insert_errors = TRUE;
    $v3200_update .= "<li>Addition of ".$row['brewStyle']." failed. Error: ".$db_conn->getLastError()."</li>";
    $error_count += 1;
  }
}
if ($inserted > 0) $v3200_update .= "<li>Added ".$inserted." BJCP 2026 Mead Styles to styles table".(($skipped > 0) ? " (".$skipped." already present, skipped)" : "").".</li>";
elseif (!$insert_errors) $v3200_update .= "<li>BJCP 2026 Mead Styles already present in styles table - nothing to add.</li>";
